  # Render an outline icon. The caller's :class carries size + color, e.g.:
  #   <%= icon(:calendar_days, class: "w-5 h-5 mr-2") %>
  #   <%= icon(:user, class: "w-6 h-6 text-sky-600 dark:text-sky-400") %>
  # Unknown names render nothing (so a typo never blows up a view).
  def icon(name, **options)
    inner = ICONS[name.to_sym]
    return "".html_safe unless inner

    attrs = {
      class: "w-5 h-5",
      fill: "none",
      "viewBox" => "0 0 24 24",
      "stroke-width" => "1.5",
      stroke: "currentColor",
      "aria-hidden" => "true"
    }.merge(options)

    content_tag(:svg, inner.html_safe, attrs)
  end
end
